/*
 * The docs home body: three landing-style rows, each a short title, one lead
 * line and a compact list of destinations beside an Anatomy figure
 * (public/figures, generated by scripts/generate-figures.mjs). Rows alternate
 * sides on wide screens, as the landing's feature rows do.
 */

interface RowLink {
  description: string;
  href: string;
  title: string;
}

export interface FeatureRow {
  figure: "dock" | "rack" | "yard";
  id: string;
  lead: string;
  links: RowLink[];
  title: string;
}

