function Figure({ name }: { name: FeatureRow["figure"] }) {
  // Decorative: the row's title and links carry the meaning. No panel: the
  // drawing's paper is the page background, as on the landing.
  return (
    <div>
      <Image
        alt=""
        className="h-auto w-full dark:hidden"
        height={420}
        src={`/figures/${name}-light.svg`}
        unoptimized
        width={640}
      />
      <Image
        alt=""
        className="hidden h-auto w-full dark:block"
        height={420}
        src={`/figures/${name}-dark.svg`}
        unoptimized
        width={640}
      />
    </div>
  );
}

function Row({ row, flip }: { flip: boolean; row: FeatureRow }) {
  const headingId = `${row.id}-heading`;
  return (
    <section
      aria-labelledby={headingId}
      className={`${landingSectionClass} grid items-center gap-10 lg:grid-cols-2 lg:gap-16`}
      id={row.id}
    >
      <div className={flip ? "lg:order-2" : undefined}>
        <h2 className={landingSectionTitleClass} id={headingId}>
          {row.title}
        </h2>
        <p className={landingSubheadlineClass}>{row.lead}</p>
        <ul className="mt-8 grid gap-x-8 sm:grid-cols-2">
          {row.links.map((link) => (
            <li key={link.href}>
              <Link
                className="group flex items-start justify-between gap-3 py-3 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-fd-ring"
                href={link.href}
              >
                <span>
                  <span className="block font-medium text-fd-foreground text-sm">
                    {link.title}
                  </span>
                  <span className="mt-0.5 block text-fd-muted-foreground text-sm">
                    {link.description}
                  </span>
                </span>
                <ArrowRight
                  aria-hidden="true"
                  className="mt-0.5 size-4 shrink-0 text-fd-muted-foreground transition-[translate,color] group-hover:text-fd-foreground motion-safe:group-hover:translate-x-0.5"
                />
              </Link>
            </li>
          ))}
        </ul>
      </div>
      <Figure name={row.figure} />
    </section>
  );
}

export function FeatureRows() {
  return (
    <>
      {FEATURE_ROWS.map((row, index) => (
        <Row flip={index % 2 === 1} key={row.id} row={row} />
      ))}
    </>
  );
}
